package dev.pocket.agent;
import android.widget.*;
import org.json.*;
import java.util.regex.*;

/** A small native, OpenUI-inspired result vocabulary. Data only, never executable HTML. */
final class ChatCards {
 static boolean render(BotsActivity app,LinearLayout parent,String source,ChatMarkdown markdown){Matcher match=Pattern.compile("```pocko-ui\\s*\\n([\\s\\S]*?)```",Pattern.CASE_INSENSITIVE).matcher(source);boolean found=false;int end=0;while(match.find()){JSONObject data;try{data=new JSONObject(match.group(1));if(!java.util.Arrays.asList("card","checklist","metrics","actions").contains(data.optString("type")))continue;}catch(Exception e){continue;}if(match.start()>end){TextView plain=app.text(source.substring(end,match.start()).trim(),14);markdown.set(plain,source.substring(end,match.start()));parent.addView(plain);}LinearLayout card=app.column();card.setPadding(app.dp(12),app.dp(12),app.dp(12),app.dp(12));AgentStyle.card(card);if(!data.optString("title").isEmpty()){TextView title=app.text(limit(data.optString("title"),180),17);title.setTypeface(AgentStyle.font(app),android.graphics.Typeface.BOLD);card.addView(title);}if(!data.optString("body").isEmpty()){TextView body=app.text("",14);markdown.set(body,limit(data.optString("body"),6000));card.addView(body);}JSONArray items=data.optJSONArray("items");if(items!=null)for(int i=0;i<Math.min(20,items.length());i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String label=limit(item.optString("label"),1000),value=limit(item.optString("value"),1000);if(data.optString("type").equals("checklist"))label=(item.optBoolean("checked")?"[x] ":"[ ] ")+label;card.addView(app.text(label+(value.isEmpty()?"":"  "+value),14));String url=item.optString("url");try{java.net.URI uri=java.net.URI.create(url);if(java.util.Arrays.asList("https","http").contains(uri.getScheme())&&uri.getHost()!=null&&uri.getUserInfo()==null)app.button(card,"Open "+limit(item.optString("label","link"),60),()->app.openUrl(url),false);}catch(Exception ignored){}}parent.addView(card);end=match.end();found=true;}if(found&&end<source.length()){TextView tail=app.text("",14);markdown.set(tail,source.substring(end));parent.addView(tail);}return found;}
 private static String limit(String s,int max){return s.length()>max?s.substring(0,max):s;}
}
